CREATE TABLE gesher_config (id INTEGER PRIMARY KEY CHECK(id=1), mode TEXT NOT NULL DEFAULT 'dry_run' CHECK(mode IN ('dry_run','enabled','paused')), template_version TEXT NOT NULL, approval_digest TEXT, watch_from INTEGER NOT NULL, approved_at INTEGER, approved_by TEXT, scan_page TEXT, baseline_page TEXT, baseline_done INTEGER NOT NULL DEFAULT 0, last_check INTEGER, last_error TEXT);
INSERT INTO gesher_config(id,template_version,watch_from) VALUES(1,'gesher-v1',CAST(strftime('%s','now') AS INTEGER)*1000);
CREATE TABLE gesher_notifications (message_id TEXT PRIMARY KEY, thread_id TEXT NOT NULL, received_at INTEGER NOT NULL, email TEXT, event_key TEXT, status TEXT NOT NULL, reason TEXT, created_at INTEGER NOT NULL);
CREATE TABLE gesher_cases (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, notification_id TEXT NOT NULL, event_key TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, checked_at INTEGER NOT NULL DEFAULT 0, contact_message_id TEXT, contact_thread_id TEXT, response_message_id TEXT, referral_message_id TEXT);
CREATE TABLE gesher_responses (message_id TEXT PRIMARY KEY, case_id TEXT NOT NULL, received_at INTEGER NOT NULL, decision TEXT NOT NULL, excerpt TEXT NOT NULL);
CREATE TABLE gesher_outbox (id TEXT PRIMARY KEY, case_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('clarification','referral')), state TEXT NOT NULL CHECK(state IN ('pending','sending','sent','uncertain','blocked')), rfc_id TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, attempted_at INTEGER, sent_at INTEGER, gmail_id TEXT, thread_id TEXT, error TEXT, UNIQUE(case_id,kind));
CREATE INDEX gesher_case_poll ON gesher_cases(status,checked_at);
CREATE TABLE gesher_log (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at INTEGER NOT NULL, case_id TEXT, event TEXT NOT NULL, detail TEXT NOT NULL);
